import { randomInt } from 'node:crypto';
import type { CacheStore } from '../../../shared/cache.js';

/** Who a pairing code was generated by, and for which workspace. */
export interface PairingGrant {
  readonly workspaceId: string;
  readonly workspaceName: string;
  readonly actorId: string;
}

export const PAIRING_TTL_SECONDS = 10 * 60;
// No 0/O or 1/I/L: the code may be typed by hand from another screen.
const ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';

/**
 * One-time codes that pair a Telegram chat with a workspace. They live in the shared cache
 * (Redis when configured), so the instance that receives `/start CODE` need not be the one
 * that generated it.
 */
export class TelegramPairingCodes {
  constructor(private readonly store: CacheStore) {}

  async create(grant: PairingGrant): Promise<{ code: string; expiresAt: Date }> {
    const code = Array.from({ length: 8 }, () => ALPHABET[randomInt(ALPHABET.length)]).join('');
    await this.store.set(key(code), JSON.stringify(grant), PAIRING_TTL_SECONDS);
    return { code, expiresAt: new Date(Date.now() + PAIRING_TTL_SECONDS * 1000) };
  }

  /** The grant of a valid code, which then stops working. */
  async consume(code: string): Promise<PairingGrant | null> {
    const normalized = code.trim().toUpperCase();
    if (!/^[A-Z0-9]{8}$/.test(normalized)) return null;
    const raw = await this.store.get(key(normalized));
    if (!raw) return null;
    await this.store.set(key(normalized), '', 1);
    try {
      return JSON.parse(raw) as PairingGrant;
    } catch {
      return null;
    }
  }
}

function key(code: string): string {
  return `telegram:pairing:${code}`;
}
